{
	"name": "clinical-medication-safety-platform",
	"private": true,
	"type": "module",
	"scripts": {
		"test": "vitest run --passWithNoTests"
	},
	"devDependencies": {
		"typescript": "^5.5.4",
		"vitest": "^2.1.9"
	}
}

{
	"compilerOptions": {
		"target": "ES2022",
		"module": "NodeNext",
		"moduleResolution": "NodeNext",
		"strict": true,
		"noImplicitAny": true,
		"noUncheckedIndexedAccess": true,
		"skipLibCheck": true
	},
	"include": ["src", "test"]
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
	test: {
		include: ['test/**/*.test.ts'],
		environment: 'node',
	},
});

export type PatientId = string & { readonly __brand: 'PatientId' };
export type MedicationConceptId = string & { readonly __brand: 'MedicationConceptId' };
export type PrescriberId = string & { readonly __brand: 'PrescriberId' };
export type PharmacyId = string & { readonly __brand: 'PharmacyId' };
export type CaregiverId = string & { readonly __brand: 'CaregiverId' };
export type RuleId = string & { readonly __brand: 'RuleId' };

export type AlertSeverity = 'contraindicated' | 'serious' | 'moderate' | 'informational';
export type DiscrepancyClass = 'intentional-documented' | 'intentional-undocumented' | 'unintentional';
export type AdherenceState = 'taken' | 'missed' | 'skipped-by-instruction' | 'held-by-clinician' | 'unknown';
export type TaskType = 'caregiver-follow-up' | 'clinician-review' | 'refill-request' | 'patient-education';

export type InteractionPair = { drugA: MedicationConceptId; drugB: MedicationConceptId; severity: AlertSeverity; evidence: string };
export type TherapeuticClassEntry = { className: string; members: MedicationConceptId[] };
export type BetaLactamSideChainEntry = { drug: MedicationConceptId; sideChainGroup: string; crossReactivityRisk: 'low' | 'moderate' | 'high' };
export type DoseCeiling = { ingredient: MedicationConceptId; maxDailyMg: number; source: string };
export type RxNormNode = { rxcui: MedicationConceptId; termType: 'IN' | 'PIN' | 'MIN' | 'SCD' | 'SBD' | 'BN' | 'NDC'; name: string; parentRxcuis: MedicationConceptId[]; ingredients?: MedicationConceptId[] };

export type ReferencePack = {
	version: string;
	source: string;
	confidence: 'illustrative' | 'expert-reviewed';
	interactions: InteractionPair[];
	therapeuticClasses: TherapeuticClassEntry[];
	betaLactamSideChains: BetaLactamSideChainEntry[];
	doseCeilings: DoseCeiling[];
	rxNormGraph: RxNormNode[];
};

import { describe, expect, it } from 'vitest';
import type { AdherenceState, AlertSeverity, DiscrepancyClass, MedicationConceptId, PatientId, ReferencePack, TaskType } from '../src/core/types.js';

describe('core types', () => {
	it('compiles literal values of every exported type', () => {
		const pid = 'p-001' as unknown as PatientId;
		const cid = 'rx-100' as unknown as MedicationConceptId;
		const severity: AlertSeverity = 'serious';
		const discrepancy: DiscrepancyClass = 'unintentional';
		const adherence: AdherenceState = 'held-by-clinician';
		const task: TaskType = 'refill-request';
		const pack: ReferencePack = { version: '0', source: 'fixture', confidence: 'illustrative', interactions: [], therapeuticClasses: [], betaLactamSideChains: [], doseCeilings: [], rxNormGraph: [] };
		expect([pid, cid, severity, discrepancy, adherence, task, pack.version].length).toBe(7);
	});
});

export interface Clock {
	now(): Date;
}

import type { Clock } from './clock.js';

export class FixedClock implements Clock {
	constructor(private readonly fixedTime: Date) {}

	now(): Date {
		return new Date(this.fixedTime.getTime());
	}
}

import { describe, expect, it } from 'vitest';
import { FixedClock } from '../src/core/fixed-clock.js';

describe('FixedClock', () => {
	it('returns the fixed instant as ISO', () => {
		const clock = new FixedClock(new Date('2025-01-15T08:00:00Z'));
		expect(clock.now().toISOString()).toBe('2025-01-15T08:00:00.000Z');
	});
	it('clones on every call', () => {
		const clock = new FixedClock(new Date('2025-01-15T08:00:00Z'));
		const a = clock.now();
		const b = clock.now();
		expect(a.getTime()).toBe(b.getTime());
		expect(a).not.toBe(b);
	});
});

export type DoseUnit = 'mg' | 'mg/kg' | 'mg/kg/day' | 'mcg' | 'g';
export type FrequencyUnit = 'daily' | 'twice-daily' | 'three-times-daily' | 'four-times-daily' | 'every-6h' | 'every-8h' | 'every-12h' | 'as-needed';
export type WeightUnit = 'kg' | 'lb';
export type Quantity = { value: number; unit: DoseUnit };
export type Weight = { value: number; unit: WeightUnit };

export class UnitMismatchError extends Error {
	constructor(message: string) {
		super(message);
		this.name = 'UnitMismatchError';
	}
}

export function toKg(w: Weight): Weight {
	return w.unit === 'lb' ? { value: w.value / 2.2, unit: 'kg' } : { ...w };
}

const DAILY_MULTIPLIER: Record<FrequencyUnit, number | null> = {
	daily: 1,
	'twice-daily': 2,
	'three-times-daily': 3,
	'four-times-daily': 4,
	'every-6h': 4,
	'every-8h': 3,
	'every-12h': 2,
	'as-needed': null,
};

export function frequencyToDailyMultiplier(f: FrequencyUnit): number | null {
	return DAILY_MULTIPLIER[f];
}

export function dailyDoseMg(dose: Quantity, freq: FrequencyUnit, weightKg?: number): number | null {
	const multiplier = frequencyToDailyMultiplier(freq);
	if (multiplier === null) return null;
	switch (dose.unit) {
		case 'mg':
			return dose.value * multiplier;
		case 'mcg':
			return (dose.value * multiplier) / 1000;
		case 'g':
			return dose.value * multiplier * 1000;
		case 'mg/kg':
			if (weightKg === undefined) throw new UnitMismatchError('weight required for mg/kg dosing');
			return dose.value * weightKg * multiplier;
		case 'mg/kg/day':
			if (weightKg === undefined) throw new UnitMismatchError('weight required for mg/kg/day dosing');
			return dose.value * weightKg;
		default:
			throw new UnitMismatchError('unsupported dose unit: ' + String(dose.unit));
	}
}

import { describe, expect, it } from 'vitest';
import { dailyDoseMg, frequencyToDailyMultiplier, toKg, UnitMismatchError } from '../src/core/dose.js';

describe('dose arithmetic', () => {
	it('converts lb to kg at 2.2 lb per kg', () => {
		expect(toKg({ value: 220, unit: 'lb' }).value).toBeCloseTo(100, 2);
	});
	it('folds frequency into a daily multiplier', () => {
		expect(frequencyToDailyMultiplier('every-6h')).toBe(4);
	});
	it('computes plain-mg and weight-based daily doses', () => {
		expect(dailyDoseMg({ value: 500, unit: 'mg' }, 'four-times-daily')).toBe(2000);
		expect(dailyDoseMg({ value: 10, unit: 'mg/kg' }, 'twice-daily', 70)).toBe(1400);
	});
	it('throws UnitMismatchError when weight is required but missing', () => {
		expect(() => dailyDoseMg({ value: 10, unit: 'mg/kg' }, 'twice-daily')).toThrow(UnitMismatchError);
	});
	it('throws UnitMismatchError for unsupported units instead of coercing', () => {
		expect(() => dailyDoseMg({ value: 1, unit: 'iu' as never }, 'daily')).toThrow(UnitMismatchError);
	});
	it('returns null for as-needed schedules', () => {
		expect(dailyDoseMg({ value: 5, unit: 'mg' }, 'as-needed')).toBeNull();
	});
});

import type { MedicationConceptId, RxNormNode } from './types.js';

export type ResolvedConcept = { rxcui: MedicationConceptId; termType: RxNormNode['termType']; name: string; ingredients: MedicationConceptId[] };
export type UnmatchedConcept = { inputText: string; reason: 'not-found' | 'ambiguous'; blocksReconciliation: true };
export type ResolutionResult = { matched: ResolvedConcept } | { unmatched: UnmatchedConcept };

export class MedicationConceptResolver {
	constructor(private readonly graph: RxNormNode[]) {}

	resolve(input: string): ResolutionResult {
		const needle = input.trim().toLowerCase();
		const exact = this.graph.find((n) => (n.rxcui as unknown as string) === input.trim());
		const byName = exact ?? this.graph.find((n) => n.name.toLowerCase() === needle);
		if (byName) return { matched: this.toResolved(byName) };
		const partial = this.graph.filter((n) => n.name.toLowerCase().includes(needle));
		if (partial.length === 1) return { matched: this.toResolved(partial[0]!) };
		if (partial.length > 1) return { unmatched: { inputText: input, reason: 'ambiguous', blocksReconciliation: true } };
		return { unmatched: { inputText: input, reason: 'not-found', blocksReconciliation: true } };
	}

	getIngredients(rxcui: MedicationConceptId): MedicationConceptId[] {
		const node = this.graph.find((n) => n.rxcui === rxcui);
		if (!node) return [];
		if (node.termType === 'IN') return [node.rxcui];
		const direct = node.ingredients ?? [];
		if (direct.length > 0) return direct.flatMap((i) => this.getIngredients(i));
		return node.parentRxcuis.flatMap((p) => this.getIngredients(p));
	}

	private toResolved(node: RxNormNode): ResolvedConcept {
		return { rxcui: node.rxcui, termType: node.termType, name: node.name, ingredients: this.getIngredients(node.rxcui) };
	}
}

import { describe, expect, it } from 'vitest';
import { MedicationConceptResolver } from '../src/core/medication-concept-resolver.js';
import { FIXTURE_RXNORM_GRAPH } from '../src/fixtures/rxnorm-graph.js';

const resolver = new MedicationConceptResolver(FIXTURE_RXNORM_GRAPH);

describe('MedicationConceptResolver', () => {
	it('resolves a brand name to its SBD', () => {
		const r = resolver.resolve('Tylenol 500 MG Oral Tablet');
		expect('matched' in r && r.matched.termType).toBe('SBD');
	});
	it('resolves case-insensitively to the SCD', () => {
		const r = resolver.resolve('fluoxetine 20 mg oral capsule');
		expect('matched' in r && r.matched.termType).toBe('SCD');
	});
	it('returns a blocking unmatched state for free text', () => {
		const r = resolver.resolve('a water pill');
		expect('unmatched' in r && r.unmatched.blocksReconciliation).toBe(true);
	});
	it('decomposes the combo MIN into both ingredient INs', () => {
		const min = FIXTURE_RXNORM_GRAPH.find((n) => n.termType === 'MIN')!;
		const ins = resolver.getIngredients(min.rxcui).map(String).sort();
		expect(ins).toEqual(['rx-apap-in', 'rx-hyd-in']);
	});
});

import { describe, expect, it } from 'vitest';
import { MedicationConceptResolver } from '../src/core/medication-concept-resolver.js';
import { FIXTURE_RXNORM_GRAPH } from '../src/fixtures/rxnorm-graph.js';

const resolver = new MedicationConceptResolver(FIXTURE_RXNORM_GRAPH);

describe('resolver ambiguity and NDC lookup', () => {
	it('flags multi-match substrings as ambiguous', () => {
		const r = resolver.resolve('oral');
		expect('unmatched' in r && r.unmatched.reason).toBe('ambiguous');
	});
	it('resolves an NDC package up to the Acetaminophen ingredient', () => {
		const r = resolver.resolve('ndc-50580-449-05');
		expect('matched' in r).toBe(true);
		if ('matched' in r) {
			expect(r.matched.ingredients.map(String)).toContain('rx-apap-in');
		}
	});
	it('treats empty input as not-found', () => {
		const r = resolver.resolve('');
		expect('unmatched' in r && r.unmatched.reason === 'not-found').toBe(true);
	});
});

