import type { PatientId } from './types.js';

export type AuditEventType = 'reconciliation-decision' | 'alert-fired' | 'alert-suppressed' | 'task-created' | 'adherence-recorded';

export type AuditEvent = {
	id: string;
	type: AuditEventType;
	occurredAt: Date;
	patientId: PatientId;
	actorId: string;
	payload: Record<string, unknown>;
};

export class AuditLog {
	private readonly events: AuditEvent[] = [];
	private counter = 0;

	append(event: Omit<AuditEvent, 'id'>): AuditEvent {
		const stored: AuditEvent = { ...event, id: String(++this.counter) };
		this.events.push(stored);
		return stored;
	}

	getAll(): readonly AuditEvent[] {
		return [...this.events];
	}

	getByPatient(patientId: PatientId): readonly AuditEvent[] {
		return this.events.filter((e) => e.patientId === patientId);
	}
}

import { describe, expect, it } from 'vitest';
import { AuditLog } from '../src/core/audit-log.js';
import type { PatientId } from '../src/core/types.js';

const pidA = 'p-001' as unknown as PatientId;
const pidB = 'p-002' as unknown as PatientId;
const at = new Date('2025-01-15T08:00:00Z');

describe('AuditLog', () => {
	it('assigns deterministic sequential ids and preserves order', () => {
		const log = new AuditLog();
		const a = log.append({ type: 'alert-fired', occurredAt: at, patientId: pidA, actorId: 'engine', payload: {} });
		const b = log.append({ type: 'task-created', occurredAt: at, patientId: pidB, actorId: 'engine', payload: {} });
		expect([a.id, b.id]).toEqual(['1', '2']);
		expect(log.getAll().map((e) => e.id)).toEqual(['1', '2']);
	});
	it('filters by patient and returns defensive copies', () => {
		const log = new AuditLog();
		log.append({ type: 'alert-fired', occurredAt: at, patientId: pidA, actorId: 'engine', payload: {} });
		const all = log.getAll() as unknown as unknown[];
		all.pop();
		expect(log.getAll()).toHaveLength(1);
		expect(log.getByPatient(pidB)).toHaveLength(0);
	});
});

import type { FrequencyUnit, Quantity } from './dose.js';
import type { AlertSeverity, MedicationConceptId, PatientId, RuleId } from './types.js';

export type EvidenceRef = { packVersion: string; source: string; description: string };

export type Alert = {
	ruleId: RuleId;
	severity: AlertSeverity;
	interruptive: boolean;
	evidence: EvidenceRef[];
	suppressible: boolean;
	suppressionScope: 'this-patient' | 'always-for-pair' | null;
	recommendedAction: string;
	involvedDrugs: MedicationConceptId[];
};

export type PatientFacts = {
	patientId: PatientId;
	weightKg?: number;
	allergyIngredients: MedicationConceptId[];
	allergyClasses: string[];
};

export type RegimenItem = {
	conceptId: MedicationConceptId;
	resolvedIngredients: MedicationConceptId[];
	dose: Quantity;
	frequency: FrequencyUnit;
	status: 'active' | 'held' | 'stopped';
};

export function severityToInterruptive(severity: AlertSeverity): boolean {
	return severity === 'contraindicated' || severity === 'serious';
}

import type { Alert } from '../rule-types.js';
import { severityToInterruptive } from '../rule-types.js';
import type { RegimenItem } from '../rule-types.js';
import type { ReferencePack, RuleId } from '../types.js';

const RULE_ID = 'dup-ingredient' as unknown as RuleId;

export function checkDuplicateIngredient(regimen: RegimenItem[], pack: ReferencePack): Alert[] {
	const active = regimen.filter((r) => r.status === 'active');
	const alerts: Alert[] = [];
	for (let i = 0; i < active.length; i += 1) {
		for (let j = i + 1; j < active.length; j += 1) {
			const a = active[i]!;
			const b = active[j]!;
			const shared = a.resolvedIngredients.filter((ing) => b.resolvedIngredients.includes(ing));
			if (shared.length === 0) continue;
			alerts.push({
				ruleId: RULE_ID,
				severity: 'moderate',
				interruptive: severityToInterruptive('moderate'),
				evidence: [{ packVersion: pack.version, source: pack.source, description: 'Shared active ingredient after MIN decomposition: ' + shared.map(String).join(', ') }],
				suppressible: true,
				suppressionScope: 'this-patient',
				recommendedAction: 'Review the overlapping items with the prescriber.',
				involvedDrugs: [a.conceptId, b.conceptId],
			});
		}
	}
	return alerts;
}

import { describe, expect, it } from 'vitest';
import { checkDuplicateIngredient } from '../src/core/rules/dup-ingredient.js';
import { FIXTURE_REFERENCE_PACK } from '../src/fixtures/reference-pack.js';
import type { MedicationConceptId } from '../src/core/types.js';
import type { RegimenItem } from '../src/core/rule-types.js';

const id = (v: string) => v as unknown as MedicationConceptId;
const item = (conceptId: string, ingredients: string[]): RegimenItem => ({
	conceptId: id(conceptId),
	resolvedIngredients: ingredients.map(id),
	dose: { value: 500, unit: 'mg' },
	frequency: 'daily',
	status: 'active',
});

describe('dup-ingredient rule', () => {
	it('fires when a combo MIN overlaps a standalone ingredient', () => {
		const alerts = checkDuplicateIngredient(
			[item('rx-apap-hyd-min', ['rx-apap-in', 'rx-hyd-in']), item('rx-apap-scd', ['rx-apap-in'])],
			FIXTURE_REFERENCE_PACK,
		);
		expect(alerts).toHaveLength(1);
		expect(String(alerts[0]!.ruleId)).toBe('dup-ingredient');
	});
	it('stays silent for disjoint ingredients', () => {
		const alerts = checkDuplicateIngredient(
			[item('rx-flx-scd', ['rx-flx-in']), item('rx-apap-scd', ['rx-apap-in'])],
			FIXTURE_REFERENCE_PACK,
		);
		expect(alerts).toHaveLength(0);
	});
});

import type { Alert, RegimenItem } from '../rule-types.js';
import { severityToInterruptive } from '../rule-types.js';
import type { ReferencePack, RuleId } from '../types.js';

const RULE_ID = 'dup-class' as unknown as RuleId;

export function checkClassDuplication(regimen: RegimenItem[], pack: ReferencePack): Alert[] {
	const active = regimen.filter((r) => r.status === 'active');
	const alerts: Alert[] = [];
	for (const entry of pack.therapeuticClasses) {
		const hits = active.filter((r) => r.resolvedIngredients.some((ing) => entry.members.includes(ing)));
		if (hits.length < 2) continue;
		alerts.push({
			ruleId: RULE_ID,
			severity: 'informational',
			interruptive: severityToInterruptive('informational'),
			evidence: [{ packVersion: pack.version, source: pack.source, description: 'Multiple active agents in class ' + entry.className }],
			suppressible: true,
			suppressionScope: 'this-patient',
			recommendedAction: 'Confirm intentional dual therapy within class ' + entry.className + '.',
			involvedDrugs: hits.map((h) => h.conceptId),
		});
	}
	return alerts;
}

import { describe, expect, it } from 'vitest';
import { checkClassDuplication } from '../src/core/rules/dup-class.js';
import { FIXTURE_REFERENCE_PACK } from '../src/fixtures/reference-pack.js';
import type { MedicationConceptId } from '../src/core/types.js';
import type { RegimenItem } from '../src/core/rule-types.js';

const id = (v: string) => v as unknown as MedicationConceptId;
const ssri = (conceptId: string): RegimenItem => ({ conceptId: id(conceptId), resolvedIngredients: [id('rx-flx-in')], dose: { value: 20, unit: 'mg' }, frequency: 'daily', status: 'active' });

describe('dup-class rule', () => {
	it('fires informational for two SSRIs', () => {
		const alerts = checkClassDuplication([ssri('rx-flx-scd'), ssri('rx-prozac')], FIXTURE_REFERENCE_PACK);
		expect(alerts).toHaveLength(1);
		expect(alerts[0]!.severity).toBe('informational');
		expect(alerts[0]!.interruptive).toBe(false);
	});
	it('stays silent across classes', () => {
		const opioid: RegimenItem = { conceptId: id('rx-hyd-scd'), resolvedIngredients: [id('rx-hyd-in')], dose: { value: 5, unit: 'mg' }, frequency: 'daily', status: 'active' };
		expect(checkClassDuplication([ssri('rx-flx-scd'), opioid], FIXTURE_REFERENCE_PACK)).toHaveLength(0);
	});
});

import { dailyDoseMg } from '../dose.js';
import type { Alert, PatientFacts, RegimenItem } from '../rule-types.js';
import { severityToInterruptive } from '../rule-types.js';
import type { ReferencePack, RuleId } from '../types.js';

const RULE_ID = 'max-dose' as unknown as RuleId;

export function checkMaxDailyDose(facts: PatientFacts, regimen: RegimenItem[], pack: ReferencePack): Alert[] {
	const alerts: Alert[] = [];
	for (const item of regimen.filter((r) => r.status === 'active')) {
		const totalMg = dailyDoseMg(item.dose, item.frequency, facts.weightKg);
		if (totalMg === null) continue;
		for (const ceiling of pack.doseCeilings) {
			if (!item.resolvedIngredients.includes(ceiling.ingredient) || totalMg <= ceiling.maxDailyMg) continue;
			alerts.push({
				ruleId: RULE_ID,
				severity: 'serious',
				interruptive: severityToInterruptive('serious'),
				evidence: [{ packVersion: pack.version, source: ceiling.source, description: 'Computed ' + totalMg + ' mg/day exceeds ceiling ' + ceiling.maxDailyMg + ' mg/day for ' + String(ceiling.ingredient) }],
				suppressible: true,
				suppressionScope: 'this-patient',
				recommendedAction: 'Escalate the dose ceiling breach to the prescriber before the next administration.',
				involvedDrugs: [item.conceptId],
			});
		}
	}
	return alerts;
}

import { describe, expect, it } from 'vitest';
import { checkMaxDailyDose } from '../src/core/rules/max-dose.js';
import { FIXTURE_REFERENCE_PACK } from '../src/fixtures/reference-pack.js';
import type { MedicationConceptId, PatientId } from '../src/core/types.js';
import type { PatientFacts, RegimenItem } from '../src/core/rule-types.js';

const id = (v: string) => v as unknown as MedicationConceptId;
const facts: PatientFacts = { patientId: 'p-003' as unknown as PatientId, allergyIngredients: [], allergyClasses: [] };
