import type { Alert, PatientFacts, RegimenItem } from '../rule-types.js';
import { severityToInterruptive } from '../rule-types.js';
import type { AlertSeverity, ReferencePack, RuleId } from '../types.js';

const RULE_ID = 'allergy' as unknown as RuleId;
const RISK_TO_SEVERITY: Record<string, AlertSeverity> = { high: 'serious', moderate: 'moderate', low: 'informational' };

function buildAlert(severity: AlertSeverity, description: string, item: RegimenItem, pack: ReferencePack): Alert {
	return {
		ruleId: RULE_ID,
		severity,
		interruptive: severityToInterruptive(severity),
		evidence: [{ packVersion: pack.version, source: pack.source, description }],
		suppressible: true,
		suppressionScope: 'this-patient',
		recommendedAction: 'Verify the allergy history with the patient before administration.',
		involvedDrugs: [item.conceptId],
	};
}

export function checkAllergy(facts: PatientFacts, regimen: RegimenItem[], pack: ReferencePack): Alert[] {
	const alerts: Alert[] = [];
	for (const item of regimen.filter((r) => r.status === 'active')) {
		const exact = item.resolvedIngredients.find((ing) => facts.allergyIngredients.includes(ing));
		if (exact) {
			alerts.push(buildAlert('serious', 'Exact ingredient allergy match: ' + String(exact), item, pack));
			continue;
		}
		const allergyGroups = pack.betaLactamSideChains.filter((e) => facts.allergyIngredients.includes(e.drug));
		for (const ing of item.resolvedIngredients) {
			const entry = pack.betaLactamSideChains.find((e) => e.drug === ing);
			if (!entry || allergyGroups.length === 0) continue;
			const severity = RISK_TO_SEVERITY[entry.crossReactivityRisk] ?? 'informational';
			alerts.push(buildAlert(severity, 'Cross-reactivity via side chain ' + entry.sideChainGroup + ' (risk ' + entry.crossReactivityRisk + ')', item, pack));
		}
	}
	return alerts;
}

