import type { Alert, RegimenItem } from '../rule-types.js';
import { severityToInterruptive } from '../rule-types.js';
import type { ReferencePack, RuleId } from '../types.js';

const RULE_ID = 'contraindication' as unknown as RuleId;

export function checkContraindication(regimen: RegimenItem[], pack: ReferencePack): Alert[] {
	const active = regimen.filter((r) => r.status === 'active');
	const present = new Set(active.flatMap((r) => r.resolvedIngredients.map(String)));
	const alerts: Alert[] = [];
	for (const pair of pack.interactions) {
		if (!present.has(String(pair.drugA)) || !present.has(String(pair.drugB))) continue;
		alerts.push({
			ruleId: RULE_ID,
			severity: pair.severity,
			interruptive: severityToInterruptive(pair.severity),
			evidence: [{ packVersion: pack.version, source: pack.source, description: pair.evidence }],
			suppressible: pair.severity !== 'contraindicated',
			suppressionScope: pair.severity === 'contraindicated' ? null : 'always-for-pair',
			recommendedAction: 'Contact the prescriber about the interacting pair before the next dose.',
			involvedDrugs: [pair.drugA, pair.drugB],
		});
	}
	return alerts;
}

