import type { Clock } from './clock.js';
import type { Alert } from './rule-types.js';
import type { MedicationConceptId, PatientId, RuleId } from './types.js';

export class SuppressionCeilingError extends Error {}

export type SuppressionRecord = {
	id: string;
	ruleId: RuleId;
	involvedDrugs: MedicationConceptId[];
	scope: 'this-patient' | 'always-for-pair';
	suppressedBy: string;
	suppressedAt: Date;
	reason: string;
	patientId?: PatientId;
};

const drugKey = (drugs: MedicationConceptId[]): string => drugs.map(String).sort().join('|');

export class SuppressionStore {
	private readonly records: SuppressionRecord[] = [];
	private counter = 0;

	record(alert: Alert, scope: SuppressionRecord['scope'], suppressedBy: string, reason: string, patientId: PatientId | undefined, clock: Clock): SuppressionRecord {
		if (alert.severity === 'contraindicated') {
			throw new SuppressionCeilingError('contraindicated alerts cannot be suppressed');
		}
		const stored: SuppressionRecord = { id: String(++this.counter), ruleId: alert.ruleId, involvedDrugs: [...alert.involvedDrugs], scope, suppressedBy, suppressedAt: clock.now(), reason, patientId };
		this.records.push(stored);
		return stored;
	}

	isSuppressed(alert: Alert, patientId: PatientId): boolean {
		return this.records.some((r) => r.ruleId === alert.ruleId && drugKey(r.involvedDrugs) === drugKey(alert.involvedDrugs) && (r.scope === 'always-for-pair' || r.patientId === patientId));
	}

	getAll(): readonly SuppressionRecord[] {
		return [...this.records];
	}
}

