import { describe, expect, it } from 'vitest';
import { FixedClock } from '../src/core/fixed-clock.js';
import { SuppressionCeilingError, SuppressionStore } from '../src/core/suppression-store.js';
import type { Alert } from '../src/core/rule-types.js';
import type { AlertSeverity, MedicationConceptId, PatientId, RuleId } from '../src/core/types.js';

const clock = new FixedClock(new Date('2025-01-15T08:00:00Z'));
const pid = 'p-001' as unknown as PatientId;
const SEVERITIES: AlertSeverity[] = ['contraindicated', 'serious', 'moderate', 'informational'];

let lcgState = 42;
const nextRandom = (): number => {
	lcgState = (lcgState * 1664525 + 1013904223) % 4294967296;
	return lcgState / 4294967296;
};
const randomAlert = (): Alert => {
	const severity = SEVERITIES[Math.floor(nextRandom() * SEVERITIES.length)]!;
	return { ruleId: 'contraindication' as unknown as RuleId, severity, interruptive: true, evidence: [{ packVersion: '0.1.0-fixture', source: 'fixture', description: 'fuzz' }], suppressible: severity !== 'contraindicated', suppressionScope: 'this-patient', recommendedAction: 'review', involvedDrugs: ['rx-a', 'rx-b'].map((v) => v as unknown as MedicationConceptId) };
};

describe('suppression ceiling invariant', () => {
	it('never suppresses a contraindicated alert across 50 seeded attempts', () => {
		const store = new SuppressionStore();
		for (let i = 0; i < 50; i += 1) {
			const alert = randomAlert();
			const scope = nextRandom() < 0.5 ? 'this-patient' : 'always-for-pair';
			if (alert.severity === 'contraindicated') {
				expect(() => store.record(alert, scope, 'fuzzer', 'attempt', pid, clock)).toThrow(SuppressionCeilingError);
				expect(store.isSuppressed(alert, pid, clock)).toBe(false);
			} else {
				store.record(alert, scope, 'fuzzer', 'ok', pid, clock);
			}
		}
	});
});

import type { Clock } from './clock.js';
import type { MedicationConceptResolver } from './medication-concept-resolver.js';
import type { DiscrepancyClass, MedicationConceptId } from './types.js';

export type MedicationSource = 'imported' | 'patient-reported' | 'clinician-approved';
export type ReconciliationItem = {
	conceptId: MedicationConceptId | null;
	inputText: string;
	source: MedicationSource;
	provenance: { importedAt: Date; importedBy: string };
};
export type Discrepancy = { item: ReconciliationItem; classification: DiscrepancyClass; reason?: string };
export type ReconciliationOutput = {
	accepted: ReconciliationItem[];
	rejected: ReconciliationItem[];
	unmatched: ReconciliationItem[];
	discrepancies: Discrepancy[];
};

export function reconcile(items: ReconciliationItem[], resolver: MedicationConceptResolver, clinicianApprovedIds: MedicationConceptId[], clock: Clock): ReconciliationOutput {
	void clock;
	const output: ReconciliationOutput = { accepted: [], rejected: [], unmatched: [], discrepancies: [] };
	const approved = new Set(clinicianApprovedIds.map(String));
	for (const item of items) {
		const resolution = resolver.resolve(item.inputText);
		if ('unmatched' in resolution) {
			output.unmatched.push({ ...item, conceptId: null });
			continue;
		}
		const resolved = { ...item, conceptId: resolution.matched.rxcui };
		if (approved.has(String(resolution.matched.rxcui))) {
			output.accepted.push(resolved);
			if (item.source === 'clinician-approved') {
				output.discrepancies.push({ item: resolved, classification: 'intentional-documented', reason: 'clinician-approved without import source' });
			}
		} else {
			output.rejected.push(resolved);
			output.discrepancies.push({ item: resolved, classification: 'unintentional', reason: 'present in ' + item.source + ' but absent from clinician-approved regimen' });
		}
	}
	return output;
}

