import type { AdherenceState, MedicationConceptId, PatientId } from './types.js';

export type AdherenceEvent = {
	patientId: PatientId;
	conceptId: MedicationConceptId;
	scheduledAt: Date;
	state: AdherenceState;
	recordedAt: Date;
	recordedBy: string;
};

export type AdherenceSummary = {
	patientId: PatientId;
	conceptId: MedicationConceptId;
	periodStart: Date;
	periodEnd: Date;
	taken: number;
	missed: number;
	skippedByInstruction: number;
	heldByClinician: number;
	unknown: number;
	total: number;
};

export function summarizeAdherence(events: AdherenceEvent[], patientId: PatientId, conceptId: MedicationConceptId, periodStart: Date, periodEnd: Date): AdherenceSummary {
	const inPeriod = events.filter((e) => e.patientId === patientId && e.conceptId === conceptId && e.scheduledAt.getTime() >= periodStart.getTime() && e.scheduledAt.getTime() < periodEnd.getTime());
	const count = (state: AdherenceState): number => inPeriod.filter((e) => e.state === state).length;
	return {
		patientId,
		conceptId,
		periodStart,
		periodEnd,
		taken: count('taken'),
		missed: count('missed'),
		skippedByInstruction: count('skipped-by-instruction'),
		heldByClinician: count('held-by-clinician'),
		unknown: count('unknown'),
		total: inPeriod.length,
	};
}

