import type { PatientId, TaskType } from './types.js';

export type SafetyTask = {
	id: string;
	type: TaskType;
	patientId: PatientId;
	createdAt: Date;
	evidenceAlertId?: string;
	evidenceRefillForecastId?: string;
	description: string;
	traceToFacts: string[];
};

const severityToTask = (alert: Alert): TaskType => {
	if (alert.severity === 'contraindicated' || alert.severity === 'serious') return 'clinician-review';
	return alert.severity === 'moderate' ? 'caregiver-follow-up' : 'patient-education';
};

export class TaskQueue {
	private readonly tasks: SafetyTask[] = [];
	private counter = 0;

	createFromAlert(alert: Alert, patientId: PatientId, clock: Clock, auditLog: AuditLog): SafetyTask {
		const task: SafetyTask = { id: 'task-' + String(++this.counter), type: severityToTask(alert), patientId, createdAt: clock.now(), evidenceAlertId: String(alert.ruleId), description: alert.recommendedAction, traceToFacts: alert.involvedDrugs.map(String) };
		this.tasks.push(task);
		auditLog.append({ type: 'task-created', occurredAt: task.createdAt, patientId, actorId: 'task-queue', payload: { taskId: task.id, ruleId: String(alert.ruleId) } });
		return task;
	}

	createFromRefillRisk(forecast: RefillForecast, patientId: PatientId, clock: Clock, auditLog: AuditLog): SafetyTask {
		const task: SafetyTask = { id: 'task-' + String(++this.counter), type: 'refill-request', patientId, createdAt: clock.now(), evidenceRefillForecastId: String(forecast.conceptId), description: 'Request a refill before projected exhaustion.', traceToFacts: [String(forecast.conceptId), 'daysUntilExhaustion=' + String(forecast.daysUntilExhaustion)] };
		this.tasks.push(task);
		auditLog.append({ type: 'task-created', occurredAt: task.createdAt, patientId, actorId: 'task-queue', payload: { taskId: task.id, conceptId: String(forecast.conceptId) } });
		return task;
	}

	getAll(): readonly SafetyTask[] {
		return [...this.tasks];
	}

	getByPatient(patientId: PatientId): readonly SafetyTask[] {
		return this.tasks.filter((t) => t.patientId === patientId);
	}
}

