import { describe, expect, it } from 'vitest';
import { checkClassDuplication } from '../src/core/rules/dup-class.js';
import { FIXTURE_REFERENCE_PACK } from '../src/fixtures/reference-pack.js';
import type { RegimenItem } from '../src/core/rule-types.js';

let lcgState = 42;
const nextRandom = (): number => {
	lcgState = (lcgState * 1664525 + 1013904223) % 4294967296;
	return lcgState / 4294967296;
};

describe('same-class duplication property', () => {
	it('fires dup-class for 20 random same-class pairs', () => {
		const classes = FIXTURE_REFERENCE_PACK.therapeuticClasses.filter((c) => c.members.length >= 2);
		expect(classes.length).toBeGreaterThan(0);
		for (let i = 0; i < 20; i += 1) {
			const entry = classes[Math.floor(nextRandom() * classes.length)]!;
			const [m1, m2] = [entry.members[0]!, entry.members[1]!];
			const regimen: RegimenItem[] = [m1, m2].map((ing) => ({ conceptId: ing, resolvedIngredients: [ing], dose: { value: 10, unit: 'mg' }, frequency: 'daily', status: 'active' }));
			const alerts = checkClassDuplication(regimen, FIXTURE_REFERENCE_PACK);
			expect(alerts.some((a) => a.evidence[0]!.description.includes(entry.className))).toBe(true);
		}
	});
});

import type { AuditLog } from './audit-log.js';

export function projectTaskCounts(auditLog: AuditLog): Map<string, number> {
	const counts = new Map<string, number>();
	for (const event of auditLog.getAll()) {
		if (event.type !== 'task-created') continue;
		const key = String(event.patientId);
		counts.set(key, (counts.get(key) ?? 0) + 1);
	}
	return counts;
}

export function projectAdherenceRecordCounts(auditLog: AuditLog): Map<string, number> {
	const counts = new Map<string, number>();
	for (const event of auditLog.getAll()) {
		if (event.type !== 'adherence-recorded') continue;
		const key = String(event.patientId);
		counts.set(key, (counts.get(key) ?? 0) + 1);
	}
	return counts;
}

import { describe, expect, it } from 'vitest';
import { AuditLog } from '../src/core/audit-log.js';
import { projectAdherenceRecordCounts, projectTaskCounts } from '../src/core/audit-projections.js';
import type { PatientId } from '../src/core/types.js';

const pidA = 'p-001' as unknown as PatientId;
const pidB = 'p-002' as unknown as PatientId;
const at = new Date('2025-01-15T08:00:00Z');

describe('audit projections', () => {
	it('folds task-created and adherence-recorded events per patient', () => {
		const log = new AuditLog();
		log.append({ type: 'task-created', occurredAt: at, patientId: pidA, actorId: 'queue', payload: {} });
		log.append({ type: 'task-created', occurredAt: at, patientId: pidA, actorId: 'queue', payload: {} });
		log.append({ type: 'adherence-recorded', occurredAt: at, patientId: pidB, actorId: 'nurse', payload: {} });
		expect(projectTaskCounts(log).get('p-001')).toBe(2);
		expect(projectAdherenceRecordCounts(log).get('p-002')).toBe(1);
	});
	it('is idempotent across re-projections', () => {
		const log = new AuditLog();
		log.append({ type: 'task-created', occurredAt: at, patientId: pidA, actorId: 'queue', payload: {} });
		expect(projectTaskCounts(log)).toEqual(projectTaskCounts(log));
	});
});

import type { Alert, RegimenItem } from '../rule-types.js';
import type { ReferencePack, RuleId } from '../types.js';

const RULE_ID = 'lasa' as unknown as RuleId;

export function levenshtein(a: string, b: string): number {
	const rows = a.length + 1;
	const cols = b.length + 1;
	const d: number[][] = Array.from({ length: rows }, (_, i) => Array.from({ length: cols }, (_, j) => (i === 0 ? j : j === 0 ? i : 0)));
	for (let i = 1; i < rows; i += 1) {
		for (let j = 1; j < cols; j += 1) {
			const cost = a[i - 1] === b[j - 1] ? 0 : 1;
			d[i]![j] = Math.min(d[i - 1]![j]! + 1, d[i]![j - 1]! + 1, d[i - 1]![j - 1]! + cost);
		}
	}
	return d[rows - 1]![cols - 1]!;
}

export function checkLookAlikeSoundAlike(regimen: RegimenItem[], pack: ReferencePack): Alert[] {
	const named = regimen.filter((r) => r.status === 'active').map((r) => ({ item: r, name: pack.rxNormGraph.find((n) => n.rxcui === r.conceptId)?.name ?? String(r.conceptId) }));
	const alerts: Alert[] = [];
	for (let i = 0; i < named.length; i += 1) {
		for (let j = i + 1; j < named.length; j += 1) {
			const a = named[i]!;
			const b = named[j]!;
			if (a.name.length <= 8 || b.name.length <= 8 || levenshtein(a.name.toLowerCase(), b.name.toLowerCase()) > 2) continue;
			alerts.push({ ruleId: RULE_ID, severity: 'informational', interruptive: false, evidence: [{ packVersion: pack.version, source: pack.source, description: 'Confusable names: ' + a.name + ' vs ' + b.name }], suppressible: true, suppressionScope: 'this-patient', recommendedAction: 'Double-check the intended drug at administration time.', involvedDrugs: [a.item.conceptId, b.item.conceptId] });
		}
	}
	return alerts;
}

import { describe, expect, it } from 'vitest';
import { checkLookAlikeSoundAlike, levenshtein } from '../src/core/rules/lasa.js';
import { FIXTURE_REFERENCE_PACK } from '../src/fixtures/reference-pack.js';
import type { MedicationConceptId, ReferencePack, RxNormNode } from '../src/core/types.js';
import type { RegimenItem } from '../src/core/rule-types.js';

const id = (v: string) => v as unknown as MedicationConceptId;
const node = (rxcui: string, name: string): RxNormNode => ({ rxcui: id(rxcui), termType: 'IN', name, parentRxcuis: [] });
const pack: ReferencePack = { ...FIXTURE_REFERENCE_PACK, rxNormGraph: [...FIXTURE_REFERENCE_PACK.rxNormGraph, node('rx-hdrx-in', 'hydroxyzine'), node('rx-hdrl-in', 'hydralazine')] };
const item = (concept: string): RegimenItem => ({ conceptId: id(concept), resolvedIngredients: [id(concept)], dose: { value: 10, unit: 'mg' }, frequency: 'daily', status: 'active' });

describe('LASA rule', () => {
	it('computes edit distance', () => {
		expect(levenshtein('hydroxyzine', 'hydralazine')).toBeLessThanOrEqual(4);
		expect(levenshtein('abc', 'abc')).toBe(0);
	});
	it('surfaces a passive confusable-name alert for near-identical names', () => {
		const near: ReferencePack = { ...pack, rxNormGraph: [...pack.rxNormGraph, node('rx-a-in', 'cefuroximab'), node('rx-b-in', 'cefuroximac')] };
		const alerts = checkLookAlikeSoundAlike([item('rx-a-in'), item('rx-b-in')], near);
		expect(alerts).toHaveLength(1);
		expect(alerts[0]!.interruptive).toBe(false);
	});
});

import type { MedicationConceptResolver } from '../core/medication-concept-resolver.js';
import type { FrequencyUnit } from '../core/dose.js';
import type { RegimenItem } from '../core/rule-types.js';

export type FhirMedicationRequest = {
	status: 'active' | 'on-hold' | 'stopped' | 'completed';
	intent: 'order' | 'plan';
	medicationText: string;
	dosageInstruction: { timing: { frequency: number; period: number; periodUnit: 'd' }; doseQuantity: { value: number; unit: 'mg' } };
	dispenseRequest?: { quantityMg: number; numberOfRepeatsAllowed: number };
};

const FREQUENCY_MAP: Record<number, FrequencyUnit> = { 1: 'daily', 2: 'twice-daily', 3: 'three-times-daily', 4: 'four-times-daily' };

export type FhirImportResult = { regimenItem: RegimenItem | null; unresolvedText: string | null };

export function importMedicationRequest(request: FhirMedicationRequest, resolver: MedicationConceptResolver): FhirImportResult {
	const resolution = resolver.resolve(request.medicationText);
	if ('unmatched' in resolution) {
		return { regimenItem: null, unresolvedText: request.medicationText };
	}
	const status: RegimenItem['status'] = request.status === 'active' ? 'active' : request.status === 'on-hold' ? 'held' : 'stopped';
	return {
		regimenItem: {
			conceptId: resolution.matched.rxcui,
			resolvedIngredients: resolution.matched.ingredients,
			dose: { value: request.dosageInstruction.doseQuantity.value, unit: 'mg' },
			frequency: FREQUENCY_MAP[request.dosageInstruction.timing.frequency] ?? 'daily',
			status,
		},
		unresolvedText: null,
	};
}

import { describe, expect, it } from 'vitest';
import { importMedicationRequest, type FhirMedicationRequest } from '../src/adapters/fhir-import.js';
import { MedicationConceptResolver } from '../src/core/medication-concept-resolver.js';
import { FIXTURE_RXNORM_GRAPH } from '../src/fixtures/rxnorm-graph.js';

const resolver = new MedicationConceptResolver(FIXTURE_RXNORM_GRAPH);
const order = (status: FhirMedicationRequest['status'], medicationText: string): FhirMedicationRequest => ({ status, intent: 'order', medicationText, dosageInstruction: { timing: { frequency: 2, period: 1, periodUnit: 'd' }, doseQuantity: { value: 500, unit: 'mg' } }, dispenseRequest: { quantityMg: 14000, numberOfRepeatsAllowed: 2 } });

describe('FHIR import adapter', () => {
	it('maps an active order to an active regimen item', () => {
		const result = importMedicationRequest(order('active', 'Amoxicillin 500 MG Oral Capsule'), resolver);
		expect(result.regimenItem?.status).toBe('active');
		expect(result.regimenItem?.frequency).toBe('twice-daily');
	});
	it('maps on-hold to held, never stopped', () => {
		const result = importMedicationRequest(order('on-hold', 'Amoxicillin 500 MG Oral Capsule'), resolver);
		expect(result.regimenItem?.status).toBe('held');
	});
	it('keeps unresolvable text as an unresolved result', () => {
		const result = importMedicationRequest(order('active', 'a water pill'), resolver);
		expect(result.regimenItem).toBeNull();
		expect(result.unresolvedText).toBe('a water pill');
	});
});
